19	/**
20	 * Converts a raw telephone into E.164 form. A leading '+' and country code are kept as given;
21	 * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
22	 * digits. Spaces, dashes and brackets are stripped, and the result must carry 8 to 15 digits after
23	 * the '+'. Returns {@code null} when no valid E.164 number can be formed.
24	 */
25	final class E164Telephone {
26	
27	    private E164Telephone() {
28	    }
29	
30	    static String toE164(String raw) {
31	        String cleaned = raw.replaceAll("[ ()\\-]", "");
32	        String digits = cleaned.startsWith("+") ? cleaned.substring(1)
33	            : "61" + (cleaned.startsWith("0") ? cleaned.substring(1) : cleaned);
34	        return digits.matches("\\d{8,15}") ? "+" + digits : null;
35	    }
36	}
